P['papa-leo-10'] = dict(name='Pope Leo X', cat='The Renaissance pope', born='Florence',
 bio='A Medici, he was a pope who loved art and Raphael. Luther’s Reformation began in his time.',
 secs=[['Art and debt', 'While money was being raised to rebuild St. Peter’s Basilica, the abuse of indulgences caused controversy. That controversy sparked Luther’s 95 theses in 1517.'],
       ['Luther', 'In 1520, with “Exsurge Domine”, he condemned forty-one of Luther’s propositions; when Luther did not back down he was excommunicated in 1521. The deep reform of the Church would be the work of later popes and of the Council of Trent.']],
 docs=[['Exsurge Domine', '1520', 'The bull condemning Luther’s propositions.']])
